import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let it = xs.iterator().map(|x| x * 2)
    let s = it.fold(100, |acc, x| acc + x)
    if s == 112 { io.println("fold-ok") } else { io.println("fold-bad") }

    return Ok(())
}
